INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-stay-1-import-v1', 'tx-stay-1', 1, 'approved', '{"title":"Chillout Village Tà Xùa","category":"homestay","area":"Khe Cải","address":"Khe Cải, Tà Xùa, Bắc Yên, Sơn La","phone":"0933669881","zalo":"0933669881","description":"Chillout Village nổi bật với không gian nghỉ dưỡng riêng tư, view thung lũng đẹp và những căn phòng kính rộng mở hướng núi. Bên cạnh hệ thống phòng tiện nghi, homestay còn có bể bơi và nhiều hoạt động giải trí, mang đến trải nghiệm thư giãn trọn vẹn giữa thiên nhiên Tà Xùa.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781170201336-644236.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781170201336-644236.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781171503178-208857.png.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781170214795-569697.png.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781170199783-26996.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781170202369-760636.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781170203208-646195.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781170203880-916530.png.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781170204850-775443.jpg.w1080.webp"],"tags":["View săn mây","Chỗ đỗ xe"],"minPrice":400000,"coordinates":null,"hasCloudView":true,"isInstantBooking":false}', 'importer', '2026-11-04T00:00:00.000Z', 'importer', '2026-11-04T00:00:00.000