INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-stay-2-import-v1', 'tx-stay-2', 1, 'approved', '{"title":"Homestay Trà Mây Tà Xùa","category":"homestay","area":"Trung Tâm Tà Xùa","address":"Khu vực khác · Bản Bẹ, xã Tà Xùa","phone":"0975091172","zalo":"0975091172","description":"TRÀ MÂY TÀ XÙA – CHẠM MÂY, THƯỞNG TRÀ, TÌM VỀ BÌNH YÊN\nẨn mình giữa núi rừng Tây Bắc hùng vĩ, Homestay Trà Mây Tà Xùa tọa lạc tại Bản Bẹ, xã Tà Xùa, Sơn La – nơi thiên nhiên giao hòa cùng nét đẹp văn hóa bản địa, mang đến một không gian nghỉ dưỡng yên bình, gần gũi và đầy cảm xúc.\nSở hữu vị trí độc đáo với tầm nhìn hướng ra hai thung lũng rộng lớn, Trà Mây là điểm dừng chân lý tưởng để du khách chiêm ngưỡng biển mây bồng bềnh, đón những tia nắng đầu ngày và tận hưởng bầu không khí trong lành giữa núi rừng. Hệ thống bungalow riêng tư cùng khu nhà sàn mang đậm nét truyền thống tạo nên không gian lưu trú ấm cúng, mộc mạc nhưng vẫn đầy đủ tiện nghi.\nKhông chỉ là nơi lưu trú, Trà Mây còn mang đến trải nghiệm văn hóa trà Shan Tuyết cổ thụ đặc trưng của vùng đất Tà Xùa. Du khách có thể thưởng thức những chén trà thơm giữa khung cảnh núi non, tìm hiểu câu chuyện về những cây trà hàng trăm năm tuổi và khám phá nét đẹp trong đời sống, văn hóa của người dân địa phương.\nNằm cách khu rừng trà cổ thụ khoảng 1 km, Trà Mây cũng là điểm khởi đầu thuận tiện cho hành trình khám phá thiên nhiên và những giá trị đặc sắc của vùng đất Tà Xùa.\nĐến với Trà Mây, mỗi chuyến đi không chỉ là hành trình săn mây, mà còn là dịp sống chậm lại, cảm nhận hương trà và lưu giữ những khoảnh khắc bình yên giữa đại ngàn Tây Bắc.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/submissions/2026-11/1793861261076-fbed0926-fd90-4ca0-83e1-8a448a17952c.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/submissions/2026-11/17