INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-stay-4-import-v1', 'tx-stay-4', 1, 'approved', '{"title":"Tà Xùa Ecolodge","category":"homestay","area":"Trung Tâm Tà Xùa","address":"Khu vực khác · Bản Chung Trinh, Xã Tà Xùa, Sơn La","phone":"0989345302","zalo":"0989345302","description":"Tà Xùa Ecolodge là khu nghỉ dưỡng sinh thái giữa núi rừng Tà Xùa, Sơn La, nơi du khách có thể tận hưởng không gian xanh yên bình giữ đồi táo mèo và chè shan tuyết, không khí trong lành và khung cảnh biển mây tuyệt đẹp. Với kiến trúc gỗ, mái Pơ Mu gần gũi thiên nhiên, nơi đây mang đến trải nghiệm nghỉ dưỡng thư thái, khám phá văn hóa bản địa và thưởng thức vẻ đẹp hoang sơ của vùng núi Tây Bắc.\n\nTà Xùa Ecolodge is a peaceful mountain retreat nestled in the beautiful highlands of Tà Xùa, Son La. Surrounded by fresh mountain air among shan tea and H''mong apple trees, lush landscapes and spectacular sea-of-cloud views, it offers a relaxing escape where guests can reconnect with nature, experience local culture and enjoy the authentic charm of Vietnam’s Northwest mountains.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/submissions/2026-11/1793595961687-cbacba42-6906-4682-beef-586aacfb4a59.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/submissions/2026-11/1793595961687-cbacba42-6906-4682-beef-586aacfb4a59.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/submissions/2026-11/1793595987258-06155992-f84e-4d0c-8a07-ee32edc51d61.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/submissions/2026-11/1793595989531-57d14948-6016-4aa5-b8d1-bb3acf994b43.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/submissions/2026-11/1793595991801-019fb0d8-102e-4f6a-be