INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-stay-66-import-v1', 'tx-stay-66', 1, 'approved', '{"title":"Homestay Tà Xùa Mùa Trứ","category":"homestay","area":"Trung Tâm Tà Xùa","address":"Trung Tâm Tà Xùa, Bắc Yên, Sơn La, Việt Nam","phone":"0967535339","zalo":"0967535339","description":"Mùa Trứ Homestay là một điểm dừng chân mang đậm nét văn hóa bản địa, mộc mạc và chân chất nằm giữa thiên đường mây Tà Xùa. Không chạy theo xu hướng hiện đại hay hào nhoáng, homestay giữ nguyên lối kiến trúc nhà gỗ mộc mạc, giản dị của đồng bào vùng cao với khoảng sân hiên rộng mở hướng thẳng ra núi đồi hoang sơ. Nơi đây mang lại một không gian tĩnh lặng, tách biệt tuyệt đối — góc lý tưởng cho những ai muốn trải nghiệm một cuộc sống \"bỏ phố về rừng\" đúng nghĩa, thong thả đón những làn gió ngàn và cảm nhận biển mây bồng bềnh lướt qua ngay trước hiên nhà.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1782210233052-324474.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1782210233052-324474.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1782210232145-5131.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1782210234037-294034.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1782210235223-201008.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1782210235919-470973.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1782210236517-172951.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1782210237204-497668.jpg.w1080.webp","https://qtkjxy