INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-stay-85-import-v1', 'tx-stay-85', 1, 'approved', '{"title":"Tà Xùa Retreat","category":"homestay","area":"Trung Tâm Tà Xùa","address":"Trung Tâm · Bản Tà Xùa C, Tà Xùa, Bắc Yên, Sơn La, Việt Nam","phone":"0336604158","zalo":"0336604158","description":"Tà Xùa Retreat mang đến một không gian nghỉ dưỡng thực sự yên bình và tĩnh lặng, tách biệt khỏi những ồn ào của khu trung tâm. Với lối kiến trúc ưu tiên sử dụng chất liệu gỗ, tre nứa tự nhiên kết hợp cùng các vách kính lớn, mỗi căn phòng tại đây đều là một góc nhỏ ấm cúng mở tầm nhìn thẳng ra thung lũng sâu hun hút. Đây là điểm dừng chân lý tưởng cho những ai muốn lười biếng nằm lướt điện thoại hay chỉ cần mở mắt thức dậy là có thể thu trọn khoảnh khắc bình minh và biển mây bồng bềnh ngay tại giường.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781258815285-144052.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781258815285-144052.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781258816131-289268.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781258816689-67324.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781258817296-205573.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781258817769-574646.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781258818373-219383.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781258818970-318945.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/pu