INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-cafe-108-import-v1', 'tx-cafe-108', 1, 'approved', '{"title":"Tiệm Cà Phê Hoàng Hôn","category":"coffee","area":"Khe Cải","address":"Bản Khe Cải, Tà Xùa, Sơn La","phone":"0963970106","zalo":"0963970106","description":"Tiệm Cà Phê Hoàng Hôn tọa lạc tại khu vực Khe Cải là một trong những tọa độ dừng chân lãng mạn và \"thơ\" bậc nhất bản mây. Đúng như tên gọi của mình, quán sở hữu vị trí đắc địa hướng thẳng về phía mặt trời lặn, nép mình bình yên giữa khung cảnh núi non trùng điệp. Không gian quán được decor vô cùng xinh xắn, tỉ mỉ với chất liệu thô mộc làm chủ đạo, mở ra một khoảng trời khoáng đạt và tự do. Đây là địa điểm lý tưởng để bạn thong thả ngồi nhâm nhi ly nước ấm, lắng nghe một bản nhạc nhẹ nhàng và ngắm nhìn vạt nắng hoàng hôn nhuộm hồng cả thung lũng mây ngàn.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783478715140-965439.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783478715140-965439.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781972702019-559912.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781972697502-280566.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781972698483-166009.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781972699197-956735.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781972700196-568868.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781972701099-832724.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase