INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-cafe-111-import-v1', 'tx-cafe-111', 1, 'approved', '{"title":"Thào Coffee Tà Xùa","category":"coffee","area":"Trung Tâm Tà Xùa","address":"Trung Tâm · Bản Tà Xùa A, Tà Xùa, Bắc Yên, Sơn La","phone":"0846298888","zalo":"0846298888","description":"Thào Coffee là quán cà phê đầu tiên và mang tính biểu tượng bậc nhất tại trung tâm Tà Xùa. Nằm ngay sát bên triền núi, quán giữ chân du khách bằng một không gian thô mộc được dựng hoàn toàn từ gỗ và lợp mái ngói âm dương sậm màu theo phong cách nhà sàn truyền thống của đồng bào H''Mông. Không chỉ là nơi thưởng thức ly cà phê ấm giữa cái lạnh vùng cao, Thào Coffee còn là một \"toạ độ\" văn hoá – nơi bạn có thể vừa chạm tay vào sương mờ, vừa cảm nhận trọn vẹn nhịp sống bình dị và nét đẹp nguyên bản của đất trời Tây Bắc.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339039005-802756.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339039005-802756.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339040514-504347.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339041604-65763.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339042360-41134.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339043471-633378.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339044393-504724.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339045252-401116.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v