INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-cafe-112-import-v1', 'tx-cafe-112', 1, 'approved', '{"title":"Nhà H''Mông","category":"coffee","area":"Trung Tâm Tà Xùa","address":"Trung Tâm Tà Xùa, Bắc Yên, Sơn La, Việt Nam","phone":"0347389375","zalo":"0347389375","description":"Nhà H''Mông Cafe là một trong những toạ độ dừng chân mang không gian văn hoá đặc trưng và mộc mạc tại Tà Xùa. Quán tái hiện hoàn hảo kiến trúc nhà ở truyền thống của đồng bào người H''Mông với vách gỗ thô mộc, cột kèo tự nhiên và mái ngói âm dương rêu phong cổ kính. Giữa cái lạnh bao phủ của vùng cao, bước vào Nhà H''Mông, bạn sẽ cảm nhận ngay sự ấm áp tỏa ra từ bếp lửa bập bùng giữa nhà, hương cà phê thơm nồng quyện cùng sắc màu rực rỡ của những tấm thổ cẩm treo tường, tạo nên một không gian trốn phố vô cùng an nhiên và hoài niệm.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339825199-974357.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339825199-974357.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339826235-213878.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339827050-187941.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339827809-242341.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339828783-292482.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339829447-859756.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781339830300-902362.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storag