INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-rest-118-import-v1', 'tx-rest-118', 1, 'approved', '{"title":"Cơm nhà Namiya - Đỉnh Gió","category":"restaurant","area":"Đỉnh Gió","address":"Đỉnh Gió, Tà Xùa, Bắc Yên, Sơn La, Việt Nam","phone":"0865292896","zalo":"0898563115","description":"Cơm nhà Namiya là một tọa độ ẩm thực mang phong cách vô cùng mộc mạc, bình dị và ngập tràn sự ấm cúng, tọa lạc ngay tại khu vực Đỉnh Gió — thiên đường săn mây nổi tiếng của Tà Xùa. Namiya giữ chân du khách bằng hương vị tinh tế của những bữa cơm nhà nóng hổi và sự hiếu khách, chân thành. Giữa cái lạnh sương mờ của vùng cao, ghé vào Namiya để thong thả thưởng thức những món ăn đậm đà bản sắc chính là trải nghiệm \"chữa lành\" chiếc bụng đói hoàn hảo, giúp bạn nạp đầy năng lượng sau những cung đường trekking và săn ảnh dài.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783951895653-561760.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783951895653-561760.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783951896685-941282.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783951897450-346939.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783951898424-104743.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783951899217-940284.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783951900352-831302.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783951901234-322452.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storag