INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-rest-119-import-v1', 'tx-rest-119', 1, 'approved', '{"title":"Nhà hàng Hang Chú - Tà Xùa","category":"restaurant","area":"Trung Tâm Tà Xùa","address":"Trung tâm Tà Xùa, huyện Bắc Yên, tỉnh Sơn La, Việt Nam","phone":"0911745198","zalo":"0898563115","description":"Nhà hàng Hang Chú & Hidden Bar là một tổ hợp ẩm thực và giải trí vô cùng độc đáo, mang phong cách mộc mạc tinh tế pha chút bí ẩn, tọa lạc ngay trong lòng bản làng Tà Xùa. Không chỉ là nơi dừng chân để lấp đầy chiếc bụng đói, Hang Chú dẫn dắt du khách vào một hành trình đánh thức mọi giác quan: từ việc thưởng thức những món ăn mang đậm tinh hoa ẩm thực Tây Bắc cho đến việc trốn mình trong một chiếc Hidden Bar đầy cá tính. Sự kết hợp ngẫu hứng giữa nếp sống bản địa hoang sơ và một chút thi vị, hiện đại của góc bar nhỏ biến nơi đây thành điểm hẹn lý tưởng để bạn thong thả tận hưởng trọn vẹn cuộc sống về đêm trên đỉnh mây.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783952565789-259691.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783952565789-259691.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783952550319-719162.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783952551328-74418.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783952552067-869552.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783952552753-683325.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1783952553390-243244.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/o