INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-rest-123-import-v1', 'tx-rest-123', 1, 'approved', '{"title":"Trạm Mây Tà Xùa","category":"restaurant","area":"Khe Cải","address":"Khe Cải, Tà Xùa, Bắc Yên, Sơn La","phone":"0987323962","zalo":"0987323962","description":"Quán Nướng Trạm Mây là tọa độ ẩm thực \"sưởi ấm\" chiếc bụng đói lý tưởng nhất của du khách khi đêm buông xuống tại Tà Xùa. Quán ghi điểm bởi không gian ăn uống quây quần, ấm cúng mang đậm phong cách dã ngoại (camping) ngoài trời bên bếp than hồng cheo leo giữa mây ngàn. Chuyên phục vụ các set nướng BBQ đa dạng từ thịt bò, thịt lợn bản cho đến gà đồi được tẩm ướp đậm đà theo gia vị mắc khén, hạt dổi đặc trưng, Trạm Mây mang lại một trải nghiệm vị giác tuyệt vời. Còn gì hạnh phúc hơn khi giữa cái lạnh thấu xương của vùng cao, bạn được ngồi cùng những người thương yêu, lắng nghe tiếng thịt nướng xèo xèo và hít hà mùi thơm nức mũi giữa đất trời Tây Bắc.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781973420068-129342.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781973420068-129342.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781973416894-915684.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781973416077-899289.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781973417783-766805.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781973418697-830364.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781973419298-570584.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781973420622-132406.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781973421219-178731.jpg.w1080.webp"],"tags":[],"minPrice":0,"coordinates":null,"hasCloudView":false,"isInstantBooking":false}', 'importer', '2026-11-04T00:00:00.000Z', 'importer', '2026-11-04T00:00:00.000Z', 'Nhập từ nguồn thu thập công khai, chưa xác minh');
