INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-rest-124-import-v1', 'tx-rest-124', 1, 'approved', '{"title":"Tiệm Mì Cay Tà Xùa","category":"restaurant","area":"Trung Tâm Tà Xùa","address":"Trung Tâm Tà Xùa, Bắc Yên, Sơn La, Việt Nam","phone":"0363962345","zalo":"0363962345","description":"Tiệm Mì Cay Tà Xùa là một tọa độ ẩm thực độc đáo và cực kỳ được lòng giới trẻ khi đến với bản mây. Giữa cái lạnh thấu xương và sương mù bao phủ đặc trưng của vùng cao, tiệm mì mang đến một luồng năng lượng ấm áp với những tô mì cay bốc khói nghi ngút, thơm phức. Không gian quán được bài trí tối giản, mộc mạc nhưng vô cùng gần gũi, mở ra tầm nhìn hướng ra thiên nhiên hoang sơ. Còn gì tuyệt vời hơn sau một chuyến chạy xe đường dài đổ đèo săn mây, bạn được ngồi quây quần cùng bạn bè, xì xụp thưởng thức hương vị cay nồng, đậm đà của tô mì giữa đất trời Tây Bắc.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781798001511-421225.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781798001511-421225.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781798002171-539430.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781798003024-867289.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781798003713-950536.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781798004329-800292.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781798004898-231484.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781798005696-10069.jpg.w1080.webp","https://qtk