INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-rest-126-import-v1', 'tx-rest-126', 1, 'approved', '{"title":"Nhà Hàng Phố Núi","category":"restaurant","area":"Sống Lưng Khủng Long","address":"Sống Lưng Khủng Long, Bản Chống Tra, Xã Háng Đồng, Huyện Bắc Yên, Sơn La","phone":"0965807840","zalo":"0965807840","description":"Nhà hàng ghi điểm với không gian rộng rãi, ấm cúng được thiết kế chủ yếu bằng chất liệu gỗ thô mộc, mang đậm phong cách kiến trúc vùng cao. Nơi đây chuyên phục vụ các món ăn đặc sản Tây Bắc như lẩu gà đen homestay tự nuôi, thịt trâu gác bếp, lợn bản nướng tảng thơm lừng quyện cùng gia vị mắc khén, hạt dổi đặc trưng. Giữa cái lạnh bao phủ của vùng cao, được ngồi quây quần bên nồi lẩu nghi ngút khói, nhâm nhi chút rượu ngô ấm nồng và ngắm nhìn sương mờ bảng lảng qua ô cửa kính lớn sẽ là trải nghiệm ẩm thực cực kỳ trọn vẹn cho du khách.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781408518415-65977.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781408518415-65977.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781408524049-896267.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781408524995-277339.jpg.w1080.webp"],"tags":[],"minPrice":0,"coordinates":null,"hasCloudView":false,"isInstantBooking":false}', 'importer', '2026-11-04T00:00:00.000Z', 'importer', '2026-11-04T00:00:00.000Z', 'Nhập từ nguồn thu thập công khai, chưa xác minh');
