INSERT OR IGNORE INTO listing_versions (id, listing_id, version_no, status, content_json, created_by, created_at, reviewed_by, reviewed_at, review_note) VALUES ('tx-rest-127-import-v1', 'tx-rest-127', 1, 'approved', '{"title":"Nhà Hàng Đồi Mây","category":"restaurant","area":"Trung Tâm Tà Xùa","address":"Trung Tâm · Bắc Yên, Sơn La","phone":"0352753377","zalo":"0352753377","description":"Nhà Hàng Đồi Mây là một điểm hẹn ẩm thực quen thuộc và vô cùng thuận tiện tọa lạc ngay tại khu vực trung tâm xã Tà Xùa. Không gian nhà hàng được thiết kế ấm cúng, rộng rãi, mở ra tầm nhìn thoáng đãng hướng về phía núi đồi mây phủ. Nơi đây chinh phục thực khách bằng một thực đơn gọi món đậm đà bản sắc Tây Bắc, nổi bật với các món ăn mộc mạc nhưng gây thương nhớ như cơm lam dẻo thơm nướng ống tre, xôi nếp nương thơm dẻo, gà bản nướng vàng ruộm da giòn hay những nồi lẩu nghi ngút khói. Đây là tọa độ dừng chân lý tưởng để sưởi ấm chiếc bụng đói của du khách sau những giờ phút miệt mài rong đuổi săn mây.","coverImage":"https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781410163976-57944.jpg.w1080.webp","images":["https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781410163976-57944.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781410161810-930250.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781410163044-238203.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781410164898-411005.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781410166062-339698.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781410166880-936185.jpg.w1080.webp","https://qtkjxyuzgrhngjyguzys.supabase.co/storage/v1/object/public/images/_v/homestays/1781410167842-91984.jpg.w